def save_runtime_state(chat_id, game_type, state):
  # Persist active game state across bot restarts.
  conn = sqlite3.connect(DB_FILE)
  cur = conn.cursor()
  if state is None:
    cur.execute('DELETE FROM game_states WHERE chat_id=? AND game_type=?', (chat_id, game_type))
  else:
    cur.execute('INSERT OR REPLACE INTO game_states(chat_id,game_type,state_json) VALUES(?,?,?)',
                (chat_id, game_type, json.dumps(state, ensure_ascii=False)))
  conn.commit(); conn.close()


def _set_warning_count(chat_id, user_id, count):
  count = max(0, int(count))
  warnings.setdefault(chat_id, {})
  if count:
    warnings[chat_id][user_id] = count
  else:
    warnings[chat_id].pop(user_id, None)
    if not warnings[chat_id]:
      warnings.pop(chat_id, None)
  conn = sqlite3.connect(DB_FILE); cur = conn.cursor()
  if count:
    cur.execute('INSERT OR REPLACE INTO warning_counts(chat_id,user_id,count) VALUES(?,?,?)',
                (chat_id, user_id, count))
  else:
    cur.execute('DELETE FROM warning_counts WHERE chat_id=? AND user_id=?', (chat_id, user_id))
  conn.commit(); conn.close()


def _load_persisted_state():
  conn = sqlite3.connect(DB_FILE); cur = conn.cursor()
  for chat_id, user_id, count in cur.execute('SELECT chat_id,user_id,count FROM warning_counts').fetchall():
    if count:
      warnings.setdefault(chat_id, {})[user_id] = count
  for chat_id, game_type, state_json in cur.execute('SELECT chat_id,game_type,state_json FROM game_states').fetchall():
    try:
      state = json.loads(state_json)
      if game_type == 'quiz': active_games[chat_id] = state
      elif game_type == 'xo': active_xo[chat_id] = state
      elif game_type == 'joker':
        state['players'] = {int(k): v for k, v in state.get('players', {}).items()}
        state['roles'] = {int(k): v for k, v in state.get('roles', {}).items()}
        state['votes'] = {int(k): int(v) for k, v in state.get('votes', {}).items()}
        state['alive'] = [int(v) for v in state.get('alive', [])]
        joker_lobby[chat_id] = state
    except Exception as exc:
      print(f'Could not restore {game_type} game for chat {chat_id}: {type(exc).__name__}')
  conn.close()


