def looks_like_ad(text):
  normalized = normalize_arabic_answer(text)
  phrases = ('للبيع', 'للاعلان', 'للاعلان', 'ترويج', 'اشترك بالقناة', 'اشترك بقناتي',
             'تابع قناتي', 'قناة جديدة', 'قروب جديد', 'عرض خاص', 'خصم خاص',
             'كود خصم', 'للطلب راسل', 'للطلب مراسلة', 'انضموا لقناتي', 'متوفر للبيع')
  return any(normalize_arabic_answer(p) in normalized for p in phrases)


def is_repeated_message(chat_id, user_id, text, window_seconds=15):
  compact = re.sub(r'\s+', ' ', (text or '').strip().casefold())
  if len(compact) < 5:
    return False
  signature = hashlib.sha256(compact.encode('utf-8')).hexdigest()
  now = time.time()
  conn = sqlite3.connect(DB_FILE); cur = conn.cursor()
  cur.execute('SELECT last_seen FROM spam_history WHERE chat_id=? AND user_id=? AND signature=?',
              (chat_id, user_id, signature))
  row = cur.fetchone()
  repeated = bool(row and now - row[0] <= window_seconds)
  cur.execute('INSERT OR REPLACE INTO spam_history(chat_id,user_id,signature,last_seen) VALUES(?,?,?,?)',
              (chat_id, user_id, signature, now))
  cur.execute('DELETE FROM spam_history WHERE last_seen < ?', (now - 3600,))
  conn.commit(); conn.close()
  return repeated

