def get_protection_markup(chat_id):
  settings = get_protection_settings(chat_id)
  btn_bad_words = '🟢 مفعّل' if settings.get('bad_words', True) else '🔴 معطّل'
  btn_links = '🟢 مفعّل' if settings.get('links', True) else '🔴 معطّل'
  btn_ads = '🟢 مفعّل' if settings.get('ads', True) else '🔴 معطّل'
  btn_spam = '🟢 مفعّل' if settings.get('spam', True) else '🔴 معطّل'
  btn_media = '🟢 مفعّل' if settings.get('lock_media', False) else '🔴 معطّل'

  keyboard = InlineKeyboardMarkup(row_width=2)
  keyboard.add(
      InlineKeyboardButton('🤬 قفل التجاوزات', callback_data='ignore'),
      InlineKeyboardButton(btn_bad_words, callback_data='toggle_bad_words'),
      InlineKeyboardButton('🔗 قفل الروابط', callback_data='ignore'),
      InlineKeyboardButton(btn_links, callback_data='toggle_links'),
      InlineKeyboardButton('📢 قفل الإعلانات', callback_data='ignore'),
      InlineKeyboardButton(btn_ads, callback_data='toggle_ads'),
      InlineKeyboardButton('⚠️ قفل التكرار', callback_data='ignore'),
      InlineKeyboardButton(btn_spam, callback_data='toggle_spam'),
      InlineKeyboardButton('🖼️ قفل الميديا', callback_data='ignore'),
      InlineKeyboardButton(btn_media, callback_data='toggle_lock_media'),
      InlineKeyboardButton('🔙 رجوع للقائمة', callback_data='menu_back'),
  )
  return keyboard


def is_developer(user):
  if not user:
    return False
  if user.id == int(DEVELOPER_ID):
    return True
  if user.username and f'@{user.username.lower()}' == DEVELOPER_USERNAME.lower():
    return True
  return False


