@bot.callback_query_handler(func=lambda call: call.data in ['toggle_bad_words', 'toggle_links', 'toggle_ads', 'toggle_spam', 'toggle_lock_media', 'ignore'])
def protection_toggle_callbacks(call):
  if call.data == 'ignore':
    return bot.answer_callback_query(call.id, 'اضغط زر الحالة لتغيير الإعداد.')
  chat_id = call.message.chat.id
  try:
    member = bot.get_chat_member(chat_id, call.from_user.id)
    if member.status not in ['creator', 'administrator']:
      return bot.answer_callback_query(call.id, 'هذه الإعدادات للمشرفين فقط.', show_alert=True)
  except Exception:
    return bot.answer_callback_query(call.id, 'تعذر التحقق من صلاحياتك.', show_alert=True)
  settings = get_protection_settings(chat_id)
  key = {
      'toggle_bad_words': 'bad_words',
      'toggle_links': 'links',
      'toggle_ads': 'ads',
      'toggle_spam': 'spam',
      'toggle_lock_media': 'lock_media',
  }[call.data]
  settings[key] = not settings[key]
  set_protection_settings(chat_id, settings)
  try:
    bot.edit_message_reply_markup(
        chat_id=chat_id,
        message_id=call.message.message_id,
        reply_markup=get_protection_markup(chat_id)
    )
  except Exception:
    pass
  bot.answer_callback_query(call.id, f'تم {"تفعيل" if settings[key] else "تعطيل"} الإعداد.')


