@bot.message_handler(
    func=lambda m: m.text and m.text.strip().startswith('الغاء الحظر')
)
def unban_user_handler(message):
  chat_id = message.chat.id
  user_id = message.from_user.id
  if RANK_LEVELS.get(get_user_rank_db(chat_id, user_id), 1) < 3:
    return bot.send_message(message.chat.id, '⚠️ أمر إلغاء الحظر مخصص للمشرفين فقط!')
  parts = message.text.strip().split()
  if len(parts) < 2 or not parts[1].isdigit():
    return bot.send_message(message.chat.id,
        '⚠️ اكتب الآيدي بعد الأمر بالشكل الصحيح:\n`الغاء الحظر 5866430318`',
        parse_mode='Markdown',
    )
  target_id = int(parts[1])
  try:
    bot.unban_chat_member(chat_id, target_id, only_if_banned=True)
    bot.send_message(message.chat.id,
        f'✅ تم إلغاء حظر العضو صاحب الآيدي `{target_id}` بنجاح!',
        parse_mode='Markdown',
    )
  except Exception:
    bot.send_message(message.chat.id, '⚠️ تعذر إلغاء الحظر.')


