# 🌟 الكتم وإلغاء الكتم
@bot.message_handler(
    func=lambda m: m.text
    and any(
        m.text.strip().startswith(cmd)
        for cmd in ['كتم', 'الغاء كتم', 'إلغاء كتم', 'الغاء الكتم', 'إلغاء الكتم']
    )
)
def mute_unmute_user_handler(message):
  chat_id = message.chat.id
  user_id = message.from_user.id
  if RANK_LEVELS.get(get_user_rank_db(chat_id, user_id), 1) < 3:
    return bot.send_message(message.chat.id, '⚠️ الكتم وإلغاء الكتم مخصص للمشرفين فقط!')

  target_user = None
  if message.reply_to_message:
    target_user = message.reply_to_message.from_user
  else:
    parts = message.text.strip().split()
    if len(parts) >= 2 and parts[-1].isdigit():
      tid = int(parts[-1])
      u_info = get_group_member_info(chat_id, tid)
      target_user = type(
          'User', (object,), {'id': tid, 'first_name': u_info['name']}
      )

  if not target_user:
    return bot.send_message(message.chat.id, '⚠️ قم بالرد على رسالة العضو المراد كتمه!')

  if is_developer(target_user):
    return bot.send_message(message.chat.id, '🔇 لا يستطيع أحد كتم مطور البوت الأسطوري ☀️')

  t_id = target_user.id
  t_name = getattr(target_user, 'first_name', f'العضو {t_id}')
  cmd = message.text.strip()

  conn = sqlite3.connect(DB_FILE)
  cursor = conn.cursor()

  if cmd == 'كتم':
    until_time = int(time.time()) + 300
    cursor.execute(
        'INSERT OR REPLACE INTO muted_users (chat_id, user_id, expires_at) VALUES (?, ?, ?)',
        (chat_id, t_id, until_time),
    )
    conn.commit()
    conn.close()
    try:
      bot.restrict_chat_member(
          chat_id, t_id, can_send_messages=False, until_date=until_time
      )
    except Exception:
      pass
    bot.send_message(message.chat.id,
        f'🔇 تم كتم العضو [{t_name}](tg://user?id={t_id}) لمدة **5 دقائق**!',
        parse_mode='Markdown',
    )
  elif cmd in ['الغاء كتم', 'إلغاء كتم', 'الغاء الكتم', 'إلغاء الكتم'] or cmd.startswith(('الغاء كتم ', 'إلغاء كتم ', 'الغاء الكتم ', 'إلغاء الكتم ')):
    cursor.execute(
        'DELETE FROM muted_users WHERE chat_id = ? AND user_id = ?',
        (chat_id, t_id),
    )
    conn.commit()
    conn.close()
    try:
      bot.restrict_chat_member(
          chat_id,
          t_id,
          can_send_messages=True,
          can_send_media_messages=True,
          can_send_other_messages=True,
          can_add_web_page_previews=True,
      )
    except Exception:
      pass
    bot.send_message(message.chat.id,
        f'🔊 تم إلغاء كتم العضو [{t_name}](tg://user?id={t_id}) بنجاح!',
        parse_mode='Markdown',
    )


