@bot.message_handler(
    func=lambda m: m.text and m.text.strip() in ['انذار', 'إنذار']
)
def manual_warn_user(message):
  chat_id = message.chat.id
  user_id = message.from_user.id
  if RANK_LEVELS.get(get_user_rank_db(chat_id, user_id), 1) < 3:
    return bot.send_message(message.chat.id, '⚠️ أمر الإنذار مخصص للمشرفين فقط!')
  if not message.reply_to_message:
    return bot.send_message(message.chat.id, '⚠️ يرجى الرد على رسالة العضو لتوجيه الإنذار!')

  target_user = message.reply_to_message.from_user
  if is_developer(target_user):
    return bot.send_message(message.chat.id, '⚠️ لا يمكنك إنذار مطور البوت الأسطوري ☀️')

  t_id = target_user.id
  t_name = target_user.first_name
  curr_warn = warnings.get(chat_id, {}).get(t_id, 0) + 1
  _set_warning_count(chat_id, t_id, curr_warn)

  if curr_warn < 3:
    bot.send_message(message.chat.id,
        f'⚠️ **تنبيه وإنذار إداري!**\nالعضو [{t_name}](tg://user?id={t_id})\n📌 **عدد الإنذارات:** ({curr_warn}/3)',
        parse_mode='Markdown',
    )
  else:
    _set_warning_count(chat_id, t_id, 0)
    until_time = int(time.time()) + 300
    store_mute(chat_id, t_id, until_time)
    try:
      bot.restrict_chat_member(
          chat_id, t_id, can_send_messages=False, until_date=until_time
      )
    except Exception:
      pass
    bot.send_message(message.chat.id,
        f'🔇 **تم كتم العضو تلقائياً!**\nتم كتم [{t_name}](tg://user?id={t_id}) لمدة **5 دقائق** لاكتمال 3 إنذارات!',
        parse_mode='Markdown',
    )


