@bot.message_handler(
    func=lambda m: bool(m.text) and (m.text.strip().casefold() == 'تاك' or m.text.strip().casefold().startswith('تاك '))
)
def tag_all_group_members(message):
  chat_id = message.chat.id
  if message.chat.type not in ('group', 'supergroup'):
    return bot.send_message(chat_id, 'أمر تاك يعمل داخل المجموعات فقط.')
  if _role_level_for_command(message) < 3:
    return bot.send_message(chat_id, '⛔ أمر تاك مخصص للأدمنية والمشرفين فقط.')
  raw_text = message.text.strip()
  custom_msg = (
      raw_text[3:].strip()
      if len(raw_text) > 3
      else 'الرجاء الانتباه، هناك رسالة مهمة للجميع!'
  )
  conn = sqlite3.connect(DB_FILE)
  cursor = conn.cursor()
  cursor.execute(
      'SELECT user_id, name FROM group_members WHERE chat_id = ? LIMIT 25',
      (chat_id,),
  )
  members = cursor.fetchall()
  conn.close()

  if not members:
    return bot.send_message(message.chat.id, '⚠️ لا يوجد أعضاء مسجلين في ذاكرة البوت بعد.')

  tag_list = ''
  for uid, name in members:
    tag_list += f'[{name}](tg://user?id={uid}) '

  try:
    bot.send_message(
        chat_id,
        f'📢 **نداء عام لكل أعضاء الكروب:**\n\n💬 **الرسالة:** {custom_msg}\n\n👥 {tag_list}',
        parse_mode='Markdown',
    )
  except Exception:
    pass


# ❌⭕ لعبة XO: لاعب ضد لاعب أو ضد إيسكانور، مع إعلان الفوز والتعادل وإعادة اللعب
XO_WINS = [(0,1,2),(3,4,5),(6,7,8),(0,3,6),(1,4,7),(2,5,8),(0,4,8),(2,4,6)]

def xo_result(board):
  for a,b,c in XO_WINS:
    if board[a] != '➖' and board[a] == board[b] == board[c]:
      return board[a]
  return 'draw' if '➖' not in board else None

def xo_winning_line(board):
  for a,b,c in XO_WINS:
    if board[a] != '➖' and board[a] == board[b] == board[c]:
      return (a,b,c)
  return ()

def xo_keyboard(game, chat_id):
  kb = InlineKeyboardMarkup(row_width=3)
  line = xo_winning_line(game['board'])
  cells = []
  for i, value in enumerate(game['board']):
    label = (value + '\u0336') if i in line else value
    if game.get('finished') == 'draw' and i == 4:
      label = '🤝'
    cells.append(InlineKeyboardButton(label, callback_data=f'xo_cell_{i}' if not game.get('finished') and value == '➖' else 'ignore'))
  kb.add(*cells)
  if game.get('mode') == 'choose':
    kb.row(InlineKeyboardButton('👤 ضد عضو', callback_data='xo_mode_pvp'), InlineKeyboardButton('🤖 ضد إيسكانور', callback_data='xo_mode_bot'))
  elif game.get('mode') == 'pvp' and not (game.get('player_x') and game.get('player_o')):
    kb.row(InlineKeyboardButton('❌ انضمام كـ ❌', callback_data='xo_join_x'), InlineKeyboardButton('⭕ انضمام كـ ⭕', callback_data='xo_join_o'))
  if game.get('finished'):
    kb.row(InlineKeyboardButton('🔄 العب مرة ثانية', callback_data='xo_again'), InlineKeyboardButton('🎮 قائمة إكس أو', callback_data='xo_menu'))
  return kb

def xo_status(game):
  px, po = game.get('player_x'), game.get('player_o')
  if game.get('finished') == 'draw':
    return '🤝 **نص اللعبة تعادل!**'
  if game.get('finished'):
    return game['finished']
  if game.get('mode') == 'choose':
    return '❌⭕ **لعبة إكس أو**\nاختار طريقة اللعب من الأزرار: ضد عضو أو ضد إيسكانور.'
  if game.get('mode') == 'pvp' and not (px and po):
    return '❌⭕ **لعبة إكس أو**\nبانتظار انضمام لاعبين اثنين. اختار رمزك من الأزرار.'
  if game.get('mode') == 'bot':
    return f'❌⭕ **إكس أو ضد إيسكانور**\n👤 أنت: ❌\n🤖 إيسكانور: ⭕\n🎯 الدور: {game["turn"]}'
  return f'❌⭕ **لعبة إكس أو**\n❌ {px["name"]}\n⭕ {po["name"]}\n🎯 الدور: {game["turn"]}'

@bot.message_handler(func=lambda m: m.text and m.text.strip().lower() in ['اكس او', 'xo', 'أكس أو'])
def start_xo_game(message):
  update_user_info(message.chat.id, message.from_user)
  game = {'board':['➖']*9,'turn':'❌','player_x':None,'player_o':None,'mode':'choose','owner_id':message.from_user.id,'finished':None}
  active_xo[message.chat.id] = game
  save_runtime_state(message.chat.id, 'xo', game)
  bot.send_message(message.chat.id, xo_status(game), reply_markup=xo_keyboard(game,message.chat.id), parse_mode='Markdown')

@bot.callback_query_handler(func=lambda call: call.data.startswith('xo_'))
def callback_xo_game(call):
  chat_id, user_id = call.message.chat.id, call.from_user.id
  game = active_xo.get(chat_id)
  if not game:
    bot.answer_callback_query(call.id, 'انتهت اللعبة؛ اكتب اكس او لبدء لعبة جديدة.')
    return
  update_user_info(chat_id, call.from_user)
  data = call.data
  if data == 'xo_mode_pvp':
    game['mode'] = 'pvp'
    bot.answer_callback_query(call.id, 'اللعب ضد عضو')
  elif data == 'xo_mode_bot':
    game.update({'mode':'bot','player_x':{'id':user_id,'name':call.from_user.first_name},'player_o':{'id':0,'name':'إيسكانور'},'turn':'❌'})
    bot.answer_callback_query(call.id, 'بدأت اللعبة ضد إيسكانور! أنت ❌')
  elif data in ('xo_join_x','xo_join_o'):
    if game.get('mode') != 'pvp':
      bot.answer_callback_query(call.id, 'اختار اللعب ضد عضو أولاً.'); return
    key = 'player_x' if data == 'xo_join_x' else 'player_o'
    if game.get(key):
      bot.answer_callback_query(call.id, 'هذا المقعد محجوز!', show_alert=True); return
    if any(p and p.get('id') == user_id for p in [game.get('player_x'),game.get('player_o')]):
      bot.answer_callback_query(call.id, 'أنت منضم بالفعل.'); return
    game[key] = {'id':user_id,'name':call.from_user.first_name}
    bot.answer_callback_query(call.id, 'تم الانضمام!')
  elif data == 'xo_menu':
    game.update({'board':['➖']*9,'turn':'❌','player_x':None,'player_o':None,'mode':'choose','finished':None})
    bot.answer_callback_query(call.id, 'رجعت قائمة إكس أو')
  elif data == 'xo_again':
    if game.get('mode') == 'bot' and user_id != game.get('owner_id'):
      bot.answer_callback_query(call.id, 'هذه لعبة عضو آخر.'); return
    mode = game.get('mode','choose')
    game.update({'board':['➖']*9,'turn':'❌','finished':None,'mode':mode})
    if mode == 'pvp': game.update({'player_x':None,'player_o':None})
    if mode == 'bot': game.update({'player_x':{'id':user_id,'name':call.from_user.first_name},'player_o':{'id':0,'name':'إيسكانور'}})
    bot.answer_callback_query(call.id, 'بدأت جولة جديدة!')
  elif data.startswith('xo_cell_'):
    if game.get('finished'):
      bot.answer_callback_query(call.id, 'انتهت اللعبة، اضغط العب مرة ثانية.'); return
    idx = int(data.rsplit('_',1)[1])
    if game['board'][idx] != '➖':
      bot.answer_callback_query(call.id, 'هذا المربع مأخوذ!'); return
    if game['mode'] == 'bot':
      if user_id != game.get('owner_id') or game['turn'] != '❌':
        bot.answer_callback_query(call.id, 'انتظر دورك!'); return
      game['board'][idx] = '❌'
      result = xo_result(game['board'])
      if result:
        game['finished'] = ('🎉 **فزت على إيسكانور!**' if result == '❌' else '🤝 **تعادل!**') if result != 'draw' else 'draw'
      else:
        game['turn'] = '⭕'
        free = [i for i,v in enumerate(game['board']) if v == '➖']
        # Try a winning move, then block the player's win, otherwise choose randomly.
        move = None
        for mark in ('⭕','❌'):
          for i in free:
            test = game['board'][:]; test[i] = mark
            if xo_result(test) == mark:
              move = i; break
          if move is not None: break
        if move is None: move = random.choice(free)
        game['board'][move] = '⭕'
        result = xo_result(game['board'])
        if result: game['finished'] = ('🤖 **إيسكانور فاز! حاول مرة ثانية.**' if result == '⭕' else '🤝 **تعادل!**') if result != 'draw' else 'draw'
        else: game['turn'] = '❌'
      bot.answer_callback_query(call.id, 'تمت حركتك!')
    else:
      px, po = game.get('player_x'), game.get('player_o')
      if not px or not po:
        bot.answer_callback_query(call.id, 'انتظر انضمام اللاعب الثاني!'); return
      current = px if game['turn'] == '❌' else po
      if current['id'] != user_id:
        bot.answer_callback_query(call.id, 'مو دورك!', show_alert=True); return
      game['board'][idx] = game['turn']
      result = xo_result(game['board'])
      if result:
        if result == 'draw': game['finished'] = 'draw'
        else:
          winner = px if result == '❌' else po
          game['finished'] = f'🏆 **الفائز: {winner["name"]} ({result})!**'
      else: game['turn'] = '⭕' if game['turn'] == '❌' else '❌'
      bot.answer_callback_query(call.id, 'تمت الحركة!')
  save_runtime_state(chat_id, 'xo', game)
  try:
    bot.edit_message_text(chat_id=chat_id,message_id=call.message.message_id,text=xo_status(game),reply_markup=xo_keyboard(game,chat_id),parse_mode='Markdown')
  except Exception:
    pass

# ✊✋✌️ حجرة ورقة مقص: اختيار حقيقي من الأزرار وحساب فوز/خسارة/تعادل
@bot.message_handler(func=lambda m: m.text and m.text.strip().lower() in ['حجرة ورقة مقص', 'حجرة', 'مقص'])
def play_rps(message):
  update_user_info(message.chat.id, message.from_user)
  kb = InlineKeyboardMarkup(row_width=3)
  kb.add(InlineKeyboardButton('👊 حجرة',callback_data='rps_rock'),InlineKeyboardButton('✋ ورقة',callback_data='rps_paper'),InlineKeyboardButton('✌️ مقص',callback_data='rps_scissors'))
  bot.send_message(message.chat.id, f'✊✋✌️ **حجرة ورقة مقص**\n{message.from_user.first_name}، اختار حركتك:', reply_markup=kb, parse_mode='Markdown')

@bot.callback_query_handler(func=lambda call: call.data in ('rps_rock', 'rps_paper', 'rps_scissors', 'rps_done'))
def callback_rps(call):
  if call.data == 'rps_done':
    bot.answer_callback_query(call.id); return
  user_move = call.data[4:]
  labels = {'rock':'👊 حجرة','paper':'✋ ورقة','scissors':'✌️ مقص'}
  bot_move = random.choice(list(labels))
  if user_move not in labels:
    bot.answer_callback_query(call.id, 'اختيار غير صحيح.'); return
  if user_move == bot_move: result = '🤝 تعادل!'
  elif (user_move,bot_move) in [('rock','scissors'),('paper','rock'),('scissors','paper')]: result = '🏆 فزت!'
  else: result = '😅 خسرت، جرّب مرة ثانية!'
  bot.answer_callback_query(call.id, result)
  kb = InlineKeyboardMarkup()
  kb.add(InlineKeyboardButton('🔁 العب مرة ثانية',callback_data='rps_again'))
  try:
    bot.edit_message_text(f'✊✋✌️ **حجرة ورقة مقص**\n👤 {call.from_user.first_name}: {labels[user_move]}\n🤖 إيسكانور: {labels[bot_move]}\n\n{result}',chat_id=call.message.chat.id,message_id=call.message.message_id,reply_markup=kb,parse_mode='Markdown')
  except Exception: pass

@bot.callback_query_handler(func=lambda call: call.data == 'rps_again')
def rps_again(call):
  kb = InlineKeyboardMarkup(row_width=3)
  kb.add(InlineKeyboardButton('👊 حجرة',callback_data='rps_rock'),InlineKeyboardButton('✋ ورقة',callback_data='rps_paper'),InlineKeyboardButton('✌️ مقص',callback_data='rps_scissors'))
  bot.answer_callback_query(call.id)
  try: bot.edit_message_text('✊✋✌️ **اختار حركتك:**',chat_id=call.message.chat.id,message_id=call.message.message_id,reply_markup=kb,parse_mode='Markdown')
  except Exception: pass

