@bot.message_handler(func=lambda m: m.text and m.text.strip().startswith('تحويل'))
def transfer_money_handler(message):
  chat_id = message.chat.id
  update_user_info(chat_id, message.from_user)
  sender_id = message.from_user.id
  parts = message.text.strip().split()
  if len(parts) < 2 or not parts[1].isdigit():
    return bot.send_message(message.chat.id, '⚠️ استخدم الأمر بالشكل بالرد على الشخص: `تحويل 5000`')
  amount = int(parts[1])
  if amount <= 0:
    return bot.send_message(message.chat.id, '⚠️ لا يمكن تحويل مبلغ سالب أو صفر!')
  if not message.reply_to_message:
    return bot.send_message(message.chat.id, '⚠️ يرجى الرد على رسالة الشخص المراد التحويل له!')

  receiver_id = message.reply_to_message.from_user.id
  if sender_id == receiver_id:
    return bot.send_message(message.chat.id, '⚠️ لا يمكنك تحويل الأموال لنفسك!')

  conn = sqlite3.connect(DB_FILE)
  cursor = conn.cursor()
  cursor.execute('SELECT balance FROM bank_accounts WHERE chat_id = ? AND user_id = ?', (chat_id, sender_id))
  s_acc = cursor.fetchone()
  if not s_acc or s_acc[0] < amount:
    conn.close()
    return bot.send_message(message.chat.id, '⚠️ ليس لديك رصيد كافٍ لإتمام التحويل!')

  cursor.execute('SELECT balance FROM bank_accounts WHERE chat_id = ? AND user_id = ?', (chat_id, receiver_id))
  r_acc = cursor.fetchone()
  if not r_acc:
    conn.close()
    return bot.send_message(message.chat.id, '⚠️ العضو ليس لديه حساب بنكي مسجل!')

  cursor.execute(
      'UPDATE bank_accounts SET balance = balance - ? WHERE chat_id = ? AND user_id = ?',
      (amount, chat_id, sender_id),
  )
  cursor.execute(
      'UPDATE bank_accounts SET balance = balance + ? WHERE chat_id = ? AND user_id = ?',
      (amount, chat_id, receiver_id),
  )
  conn.commit()
  conn.close()

  bot.send_message(message.chat.id,
      f'💸 تم تحويل مبلغ **{amount:,} دينار** بنجاح!',
      parse_mode='Markdown',
  )


@bot.message_handler(func=lambda m: m.text and m.text.strip() == 'راتبي')
def get_salary(message):
  chat_id = message.chat.id
  update_user_info(chat_id, message.from_user)
  user_id = message.from_user.id
  conn = sqlite3.connect(DB_FILE)
  cursor = conn.cursor()
  cursor.execute(
      'SELECT balance, last_salary FROM bank_accounts WHERE chat_id = ? AND user_id = ?',
      (chat_id, user_id),
  )
  acc = cursor.fetchone()

  if not acc:
    conn.close()
    return bot.send_message(message.chat.id, '⚠️ ليس لديك حساب بنكي! اكتب `تسجيل بالبنك` أولاً.'
    )

  balance, last_salary = acc
  now = time.time()
  cooldown = 1800

  if now - last_salary < cooldown:
    mins = int((cooldown - (now - last_salary)) // 60)
    conn.close()
    return bot.send_message(message.chat.id, f'⏳ الراتب لم ينزل بعد! انتظر **{mins} دقيقة** أخرى.'
    )

  job = random.choices(
      JOBS_LIST, weights=[j['chance'] for j in JOBS_LIST], k=1
  )[0]

  if job.get('risky') and random.choice([True, False]):
    cursor.execute(
        'UPDATE bank_accounts SET last_salary = ? WHERE chat_id = ? AND user_id = ?',
        (now, chat_id, user_id),
    )
    conn.commit()
    conn.close()
    return bot.send_message(message.chat.id, f'🥷 فشلت عملية السرقة كـ ({job["title"]}) وتم ضبطك ولم تحصل على شيء!'
    )

  new_balance = balance + job['salary']
  cursor.execute(
      'UPDATE bank_accounts SET balance = ?, last_salary = ? WHERE chat_id = ? AND user_id ='
      ' ?',
      (new_balance, now, chat_id, user_id),
  )
  conn.commit()
  conn.close()

  bot.send_message(message.chat.id,
      f'💼 وظيفتك المستلمة: **{job["title"]}**\n💵 الراتب المضاف: **{job["salary"]:,} دينار**\n💰 رصيدك الجديد: {new_balance:,} دينار',
      parse_mode='Markdown',
  )


