@bot.message_handler(func=lambda m: bool(m.text) and m.text.strip() == 'تنضيف')
def cleanup_inactive_bots(message):
  if _role_level_for_command(message) < 5:
    return bot.send_message(message.chat.id, 'أمر تنضيف للمشرفين والمالك فقط.')
  conn=sqlite3.connect(DB_FILE); cur=conn.cursor()
  cur.execute('SELECT user_id, name FROM group_members WHERE chat_id=?', (message.chat.id,))
  known=cur.fetchall(); conn.close()
  removed=[]
  for uid, name in known:
    try:
      member=bot.get_chat_member(message.chat.id, uid)
      if not getattr(member.user, 'is_bot', False):
        continue
      conn=sqlite3.connect(DB_FILE); cur=conn.cursor()
      cur.execute('SELECT count FROM messages_count WHERE chat_id=? AND user_id=?', (message.chat.id, uid)); row=cur.fetchone()
      conn.close()
      if row and row[0] > 0:
        continue
      # لا يستطيع البوت إخراج بوت آخر إلا إذا كانت له صلاحية حظر/طرد.
      bot.ban_chat_member(message.chat.id, uid)
      bot.unban_chat_member(message.chat.id, uid, only_if_banned=True)
      removed.append(name or str(uid))
    except Exception:
      continue
  bot.send_message(message.chat.id, f'🧹 خلص التنضيف. أزلت {len(removed)} بوت معروف بدون تفاعل مسجل. قد يتعذر الوصول لبوتات لم يسبق تسجيلها عند البوت.')


