@bot.message_handler(func=lambda m: bool(m.text) and m.text.strip() in ['الغاء الانذار', 'إلغاء الإنذار', 'الغاء الإنذار', 'إلغاء الانذار', 'الغاء انذار', 'إلغاء انذار'])
def cancel_warning_handler(message):
  if not message.reply_to_message:
    return bot.send_message(message.chat.id, 'ردّ على رسالة العضو واكتب «الغاء الانذار» حتى أعرف منو المقصود.')
  chat_id = message.chat.id
  if _role_level_for_command(message) < 3:
    return bot.send_message(chat_id, 'هذا الأمر للأدمن والمشرف والمالك فقط.')
  target = message.reply_to_message.from_user
  if target.id == message.from_user.id:
    return bot.send_message(chat_id, 'ما تحتاج تلغي إنذار لنفسك من خلال هذا الأمر.')
  if is_developer(target):
    return bot.send_message(chat_id, 'ما أگدر أغيّر إنذارات المطوّر.')
  group_warnings = warnings.get(chat_id, {})
  count = group_warnings.get(target.id, 0)
  if count <= 0:
    return bot.send_message(chat_id, f'ما عندي إنذارات مسجّلة على {target.first_name}.')
  count -= 1
  _set_warning_count(chat_id, target.id, count)
  return bot.send_message(chat_id, f'✅ ألغيت إنذار واحد عن {target.first_name}. الإنذارات الحالية: {count}/3')


# Gemini client/cache are shared across handlers to avoid recreating a client on every message.
GEMINI_ENABLED = os.getenv('GEMINI_ENABLED', '1').strip().lower() not in ('0', 'false', 'no', 'off')
GEMINI_MODEL = os.getenv('GEMINI_MODEL', 'gemini-2.5-flash').strip() or 'gemini-2.5-flash'
GEMINI_TIMEOUT_SECONDS = _bounded_int_env('GEMINI_TIMEOUT_SECONDS', 15, 5, 40)
GEMINI_CACHE_TTL = _bounded_int_env('GEMINI_CACHE_TTL', 180, 0, 3600)
GEMINI_USER_COOLDOWN = _bounded_int_env('GEMINI_USER_COOLDOWN', 3, 0, 60)
GEMINI_MAX_CONCURRENT = _bounded_int_env('GEMINI_MAX_CONCURRENT', 2, 1, 6)
GEMINI_QUEUE_WAIT_SECONDS = _bounded_int_env('GEMINI_QUEUE_WAIT_SECONDS', 4, 0, 10)
_AI_LOCK = threading.Lock()
_AI_SEMAPHORE = threading.BoundedSemaphore(GEMINI_MAX_CONCURRENT)
_AI_CLIENT = None
_AI_CLIENT_KEY = None
_AI_CACHE = {}
_AI_LAST_USER_REQUEST = {}


def get_gemini_client(api_key):
  """Reuse one Gemini client and keep network retries bounded and predictable."""
  global _AI_CLIENT, _AI_CLIENT_KEY
  with _AI_LOCK:
    if _AI_CLIENT is None or _AI_CLIENT_KEY != api_key:
      from google import genai
      from google.genai import types
      timeout_ms = GEMINI_TIMEOUT_SECONDS * 1000
      try:
        http_options = types.HttpOptions(
          timeout=timeout_ms,
          retry_options=types.HttpRetryOptions(attempts=1),
        )
      except (AttributeError, TypeError):
        # Compatibility with older google-genai versions.
        http_options = types.HttpOptions(timeout=timeout_ms)
      _AI_CLIENT = genai.Client(api_key=api_key, http_options=http_options)
      _AI_CLIENT_KEY = api_key
    return _AI_CLIENT


def _gemini_error_details(exc):
  """Return a numeric HTTP status and normalized error text without logging secrets."""
  raw_status = getattr(exc, 'code', None) or getattr(exc, 'status_code', None)
  try:
    status = int(raw_status)
  except (TypeError, ValueError):
    status_match = re.search(r'\b(400|401|403|404|408|429|500|502|503|504)\b', str(exc))
    status = int(status_match.group(1)) if status_match else None
  return status, str(exc).casefold()


def _gemini_is_quota_error(status, error_text):
  quota_signals = (
    'exceeded your current quota', 'quota exceeded', 'daily quota',
    'billing account', 'billing is not enabled', 'requests per day',
    'per-day quota', 'limit: 0', 'free tier quota',
  )
  return any(signal in error_text for signal in quota_signals)


def _gemini_is_transient(status, error_text):
  if status in (500, 502, 503, 504):
    return True
  if status == 429 and not _gemini_is_quota_error(status, error_text):
    return True
  transient_terms = ('temporarily unavailable', 'server is overloaded', 'high demand', 'try again later')
  return any(term in error_text for term in transient_terms) and not _gemini_is_quota_error(status, error_text)


def generate_escanor_ai_answer(question, message):
  if not GEMINI_ENABLED:
    return '🧠 الذكاء الاصطناعي متوقف حاليًا من إعدادات البوت.'
  api_key = (os.getenv('GEMINI_API_KEY') or GEMINI_API_KEY).strip()
  if not api_key:
    return '🧠 مفتاح Gemini غير مضبوط. أضف GEMINI_API_KEY إلى ملف .env ثم أعد تشغيل البوت.'

  question = re.sub(r'\s+', ' ', (question or '').strip())
  if not question:
    return 'اكتب سؤالك حتى أگدر أجاوبك.'
  # Bound input size so a very long Telegram message cannot make the request slow/expensive.
  question = question[:3500]
  cache_key = hashlib.sha256(question.casefold().encode('utf-8')).hexdigest()
  user_id = getattr(getattr(message, 'from_user', None), 'id', None)
  now = time.time()
  with _AI_LOCK:
    cached = _AI_CACHE.get(cache_key)
    if cached and now - cached[0] <= GEMINI_CACHE_TTL:
      return cached[1]
    if user_id is not None and GEMINI_USER_COOLDOWN:
      last = _AI_LAST_USER_REQUEST.get(user_id, 0)
      if now - last < GEMINI_USER_COOLDOWN:
        return 'لحظة حبيبي، خلّيني أكمّل الرد السابق وبعدين اسألني.'
    # Clean up long-lived in-memory state in busy groups.
    if len(_AI_LAST_USER_REQUEST) > 3000:
      cutoff = now - max(GEMINI_USER_COOLDOWN * 4, 60)
      for uid, stamp in list(_AI_LAST_USER_REQUEST.items()):
        if stamp < cutoff:
          _AI_LAST_USER_REQUEST.pop(uid, None)
    for key, item in list(_AI_CACHE.items()):
      if now - item[0] > max(GEMINI_CACHE_TTL, 1):
        _AI_CACHE.pop(key, None)

  # A short queue is friendlier than rejecting every request while two calls are active.
  acquired = _AI_SEMAPHORE.acquire(timeout=GEMINI_QUEUE_WAIT_SECONDS)
  if not acquired:
    return 'طلبات الذكاء الاصطناعي كثيرة هسه. انتظر كم ثانية وجرب مرة ثانية.'

  try:
    with _AI_LOCK:
      # Another request may have filled the cache while this one waited for a slot.
      cached = _AI_CACHE.get(cache_key)
      now = time.time()
      if cached and now - cached[0] <= GEMINI_CACHE_TTL:
        return cached[1]
      if user_id is not None and GEMINI_USER_COOLDOWN:
        last = _AI_LAST_USER_REQUEST.get(user_id, 0)
        if now - last < GEMINI_USER_COOLDOWN:
          return 'لحظة حبيبي، خلّيني أكمّل الرد السابق وبعدين اسألني.'
        # Only start the cooldown after a slot was secured; busy rejections don't penalize users.
        _AI_LAST_USER_REQUEST[user_id] = now

    from google.genai import types
    client = get_gemini_client(api_key)
    prompt = (
      'أنت إيسكانور، مساعد تيليجرام يتحدث بالعربية العراقية بشكل طبيعي ومختصر. '
      'أجب مباشرة غالبًا بجملة إلى ثلاث جمل. إذا لم تكن متأكدًا فقل ذلك ولا تخترع معلومات. '
      'لا تدّعِ أنك تعرف معلومات خاصة عن المستخدم.\n\n'
      f'السؤال: {question}'
    )
    try:
      bot.send_chat_action(message.chat.id, 'typing')
    except Exception:
      pass

    response = None
    for attempt in range(2):
      try:
        response = client.models.generate_content(
          model=GEMINI_MODEL,
          contents=prompt,
          config=types.GenerateContentConfig(max_output_tokens=180, temperature=0.5),
        )
        break
      except Exception as request_exc:
        status, error_text = _gemini_error_details(request_exc)
        if attempt == 0 and _gemini_is_transient(status, error_text):
          # A single short retry for temporary overload/rate limiting; never loop on quota errors.
          time.sleep(0.8 if status != 429 else 1.2)
          continue
        raise

    answer = (getattr(response, 'text', None) or '').strip()
    if not answer:
      return 'ما وصلني جواب من Gemini هالمرة. جرّب صياغة السؤال بشكل أبسط.'
    with _AI_LOCK:
      if GEMINI_CACHE_TTL > 0:
        _AI_CACHE[cache_key] = (time.time(), answer)
    return answer
  except Exception as exc:
    status, err = _gemini_error_details(exc)
    logger.warning('Gemini request failed: type=%s status=%s', type(exc).__name__, status or 'unknown')
    if isinstance(exc, ImportError):
      return 'مكتبة Gemini غير مثبّتة. شغّل: pip install -r requirements.txt'
    if _gemini_is_quota_error(status, err):
      return 'حصة Gemini أو الفوترة وصلت حدّها. راجع الحصة بمشروع Google AI Studio؛ إعادة المحاولة وحدها ما تحل نفاد الحصة.'
    if status == 429 or any(x in err for x in ('rate limit', 'too many requests')):
      return 'طلبات Gemini كثيرة مؤقتًا. انتظر 30–60 ثانية ثم جرّب، وتجنّب تكرار السؤال بسرعة.'
    if status in (401, 403) or any(x in err for x in ('api key', 'permission denied', 'unauthenticated')):
      return 'مفتاح Gemini غير صحيح أو ما عنده صلاحية. راجع GEMINI_API_KEY في ملف .env.'
    if status == 404 or 'model not found' in err or 'is not found' in err:
      return f'موديل Gemini غير متاح لهذا المفتاح. راجع اسم الموديل في GEMINI_MODEL (الحالي: {GEMINI_MODEL}).'
    if any(x in err for x in ('timeout', 'timed out', 'deadline exceeded')):
      return 'Gemini تأخر بالرد وانتهت مهلة الاتصال. جرّب بعد قليل؛ رفع المهلة قد يزيد الانتظار، لذلك خليها 15 ثانية مبدئيًا.'
    if status in (500, 502, 503, 504) or any(x in err for x in ('unavailable', 'overloaded', 'high demand')):
      return 'خدمة Gemini عليها ضغط مؤقت حتى بعد إعادة المحاولة مرة واحدة. انتظر دقيقة وجرب مرة ثانية.'
    return 'تعذّر الاتصال بـ Gemini. افحص اتصال الاستضافة وسجل التشغيل، بدون مشاركة المفتاح أو التوكن.'
  finally:
    _AI_SEMAPHORE.release()


@bot.message_handler(func=lambda m: bool(m.text) and m.chat.type in ['group', 'supergroup'] and any(n in m.text.casefold() for n in ['ايسكانور', 'إيسكانور', 'اسكانور', 'أيسكانور', 'أسكانور', 'إسكانور', 'يسكانور', 'آيسكانور']))
def escanor_conversation_handler(message):
  text = message.text.strip()
  low = text.casefold()
  # لا تتدخل ردود المحادثة في أوامر الإدارة أو الأوامر الأخرى.
  if any(low.startswith(x) for x in ['رفع ', 'تنزيل ', 'حظر', 'طرد', 'كتم', 'الغاء الحظر', 'إلغاء الحظر', 'انذار', 'إنذار', 'مسح', 'يوت ']):
    return
  question = text
  # يدعم صيغ الاسم الشائعة، ويحذفها من نص السؤال قبل إرساله إلى Gemini.
  for name in ['إيسكانور', 'ايسكانور', 'اسكانور', 'أيسكانور', 'أسكانور', 'إسكانور', 'يسكانور', 'آيسكانور']:
    question = question.replace(name, '')
  q = question.strip(' ،,:：!?؟!').casefold()
  facts = [
    (['عاصمة البحرين', 'عاصمه البحرين'], 'عاصمة البحرين هي المنامة 🇧🇭.'),
    (['عاصمة الإمارات', 'عاصمة الامارات', 'عاصمه الإمارات', 'عاصمه الامارات'], 'عاصمة الإمارات هي أبوظبي 🇦🇪.'),
    (['عاصمة العراق', 'عاصمه العراق'], 'عاصمة العراق هي بغداد 🇮🇶.'),
    (['عاصمة السعودية', 'عاصمه السعودية'], 'عاصمة السعودية هي الرياض 🇸🇦.'),
    (['عاصمة الكويت', 'عاصمه الكويت'], 'عاصمة الكويت هي مدينة الكويت 🇰🇼.'),
    (['عاصمة قطر', 'عاصمه قطر'], 'عاصمة قطر هي الدوحة 🇶🇦.'),
    (['عاصمة عمان', 'عاصمة عُمان', 'عاصمه عمان'], 'عاصمة سلطنة عُمان هي مسقط 🇴🇲.'),
    (['عاصمة لبنان', 'عاصمه لبنان'], 'عاصمة لبنان هي بيروت 🇱🇧.'),
    (['عاصمة مصر', 'عاصمه مصر'], 'عاصمة مصر هي القاهرة 🇪🇬.'),
    (['عاصمة الأردن', 'عاصمة الاردن', 'عاصمه الأردن', 'عاصمه الاردن'], 'عاصمة الأردن هي عمّان 🇯🇴.'),
    (['عاصمة سوريا', 'عاصمه سوريا'], 'عاصمة سوريا هي دمشق 🇸🇾.'),
    (['عاصمة تركيا', 'عاصمه تركيا'], 'عاصمة تركيا هي أنقرة 🇹🇷.'),
    (['عاصمة فرنسا', 'عاصمه فرنسا'], 'عاصمة فرنسا هي باريس 🇫🇷.'),
    (['عاصمة اليابان', 'عاصمه اليابان'], 'عاصمة اليابان هي طوكيو 🇯🇵.'),
  ]
  for keys, answer in facts:
    if any(key in q for key in keys):
      return bot.reply_to(message, answer)
  if any(x in q for x in ['منو اني', 'من أنا', 'منو أنا']):
    answer = f'أنت {message.from_user.first_name or "صديقي"}، بس ما أعرف عنك غير المعلومات الظاهرة إلي من تيليجرام.'
  elif any(x in q for x in ['شلونك', 'كيفك', 'شخبارك', 'اخبارك', 'أخبارك']):
    answer = 'تمام، حاضر وياك 😎 شنو سؤالك؟'
  elif any(x in q for x in ['شكرا', 'شكراً', 'مشكور', 'تسلم']):
    answer = 'تدلل، بالخدمة دائمًا 🤝'
  elif any(x in q for x in ['منو انت', 'من أنت', 'شنو اسمك', 'اسمك شنو']):
    answer = 'آني إيسكانور ☀️ مساعد الكروب، وأحاول أجاوبك بمعلومات مؤكدة قدر الإمكان.'
  elif any(x in q for x in ['احبك', 'أحبك']):
    answer = 'محبتك وصلت 😄 نورت الكروب.'
  elif q:
    answer = generate_escanor_ai_answer(q, message)
  else:
    answer = 'ها، آني وياك 👋 شتحتاج؟'
  return bot.reply_to(message, answer)


@bot.message_handler(func=lambda m: bool(m.text) and m.text.strip().startswith('يوت '))
def youtube_audio_handler(message):
  query = message.text.strip()[4:].strip()
  if not query:
    return bot.send_message(message.chat.id, 'اكتب اسم الأغنية بعد «يوت»، مثال: يوت اسم الأغنية')
  try:
    import yt_dlp
    import tempfile
    import glob
    tmpdir = tempfile.mkdtemp(prefix='escanor_audio_')
    bot.send_chat_action(message.chat.id, 'record_audio')
    bot.send_message(message.chat.id, '🔎 دا أبحث عن الصوت، انتظر شوي…')
    outtmpl = os.path.join(tmpdir, '%(title).80s.%(ext)s')
    title = query
    # First try converting to OGG/Opus for a Telegram voice message.
    opts = {
      'format': 'bestaudio/best',
      'outtmpl': outtmpl,
      'noplaylist': True,
      'quiet': True,
      'default_search': 'ytsearch1',
      'postprocessors': [{'key': 'FFmpegExtractAudio', 'preferredcodec': 'opus', 'preferredquality': '96'}],
    }
    try:
      with yt_dlp.YoutubeDL(opts) as ydl:
        info = ydl.extract_info('ytsearch1:' + query, download=True)
        if info.get('entries'):
          info = info['entries'][0]
        title = info.get('title', query)
    except Exception as first_exc:
      # If FFmpeg is unavailable, download the source audio and send it as a regular audio file.
      logger.warning('Voice conversion failed; trying audio-file fallback (%s)', type(first_exc).__name__)
      fallback_opts = {
        'format': 'bestaudio/best',
        'outtmpl': outtmpl,
        'noplaylist': True,
        'quiet': True,
        'default_search': 'ytsearch1',
      }
      with yt_dlp.YoutubeDL(fallback_opts) as ydl:
        info = ydl.extract_info('ytsearch1:' + query, download=True)
        if info.get('entries'):
          info = info['entries'][0]
        title = info.get('title', query)
    candidates = [f for f in glob.glob(os.path.join(tmpdir, '*')) if os.path.isfile(f) and os.path.getsize(f) > 0]
    if not candidates:
      return bot.send_message(message.chat.id, 'ما كدرت أحمّل الصوت. راجع Logs وتأكد أن الاستضافة تسمح بالتنزيل.')
    filepath = max(candidates, key=os.path.getsize)
    try:
      # If FFmpeg created an OGG/Opus file, send as a voice message.
      if filepath.lower().endswith(('.ogg', '.opus')):
        with open(filepath, 'rb') as audio_file:
          bot.send_voice(message.chat.id, audio_file, caption=title[:900])
      else:
        # Without FFmpeg, fall back to sending the downloaded audio as an audio attachment.
        with open(filepath, 'rb') as audio_file:
          bot.send_audio(message.chat.id, audio_file, title=title[:64], caption='تم إرسال الصوت كملف صوتي.')
    finally:
      import shutil
      shutil.rmtree(tmpdir, ignore_errors=True)
  except ImportError:
    bot.send_message(message.chat.id, 'ميزة يوت تحتاج مكتبة yt-dlp، وقد تحتاج الاستضافة إلى FFmpeg لتحويل الصوت.')
  except Exception as exc:
    logger.warning('YouTube audio error (%s)', type(exc).__name__)
    bot.send_message(message.chat.id, 'تعذّر جلب الصوت. افحص Logs لمعرفة السبب؛ قد يكون اتصال الاستضافة أو قيود يوتيوب أو إصدار yt-dlp.')


