@bot.message_handler(func=lambda m: bool(m.text) and m.text.strip() in ['المتصدرين','توب النقاط','لوحة المتصدرين'])
def points_leaderboard(message):
  conn=sqlite3.connect(DB_FILE); cur=conn.cursor()
  cur.execute('SELECT user_id,points,wins FROM user_points WHERE chat_id=? ORDER BY points DESC,wins DESC LIMIT 10',(message.chat.id,))
  rows=cur.fetchall(); conn.close()
  if not rows:
    return bot.send_message(message.chat.id,'🏆 ماكو متصدرين بعد. جاوب على الأسئلة حتى تجمع نقاط!')
  lines=[]
  for i,(uid,pts,wins) in enumerate(rows,1):
    info=get_group_member_info(message.chat.id,uid) or {}
    name=(info.get('name') or f'عضو {uid}').replace('[','').replace(']','')
    lines.append(f'{i}. {name} — ⭐ {pts} نقطة | 🎖️ مستوى {level_for_points(pts)} | 🏆 {wins} فوز')
  bot.send_message(message.chat.id,'🏆 **أفضل اللاعبين والمتصدرين**\n\n'+'\n'.join(lines),parse_mode='Markdown')


