@bot.message_handler(func=lambda m: bool(m.text) and m.text.strip()=='تحدي')
def create_member_challenge(message):
  if not message.reply_to_message or not message.reply_to_message.from_user:
    return bot.send_message(message.chat.id,'حتى تتحدى عضو، رد على رسالته واكتب: تحدي')
  challenger=message.from_user; opponent=message.reply_to_message.from_user
  if challenger.id==opponent.id or opponent.is_bot:
    return bot.send_message(message.chat.id,'اختَر عضواً آخر حتى تتحداه.')
  conn=sqlite3.connect(DB_FILE); cur=conn.cursor(); cur.execute('INSERT INTO member_challenges(chat_id,challenger_id,opponent_id,stake,status,created_at) VALUES(?,?,?,?,?,?)',(message.chat.id,challenger.id,opponent.id,0,'pending',time.time())); cid=cur.lastrowid; conn.commit(); conn.close()
  kb=InlineKeyboardMarkup(); kb.add(InlineKeyboardButton('⚔️ أقبل التحدي',callback_data=f'ch_accept_{cid}'),InlineKeyboardButton('❌ رفض',callback_data=f'ch_reject_{cid}'))
  bot.send_message(message.chat.id,f'⚔️ تحدي جديد!\n{challenger.first_name} يتحدى {opponent.first_name}.\n{opponent.first_name}، اقبل أو ارفض التحدي من الأزرار:',reply_markup=kb)


