@bot.callback_query_handler(func=lambda c: c.data.startswith('ch_accept_') or c.data.startswith('ch_reject_'))
def challenge_decision(call):
  try: cid=int(call.data.rsplit('_',1)[1])
  except ValueError: return bot.answer_callback_query(call.id,'تحدٍ غير صالح.',show_alert=True)
  conn=sqlite3.connect(DB_FILE); cur=conn.cursor()
  cur.execute('SELECT chat_id,challenger_id,opponent_id,status FROM member_challenges WHERE id=?',(cid,)); row=cur.fetchone()
  if not row: conn.close(); return bot.answer_callback_query(call.id,'التحدي غير موجود.',show_alert=True)
  chat_id,challenger,opponent,status=row
  if call.from_user.id!=opponent: conn.close(); return bot.answer_callback_query(call.id,'هذا التحدي موجّه لعضو آخر.',show_alert=True)
  if status!='pending': conn.close(); return bot.answer_callback_query(call.id,'تم حسم هذا التحدي سابقاً.',show_alert=True)
  if call.data.startswith('ch_reject_'):
    cur.execute('UPDATE member_challenges SET status="rejected" WHERE id=?',(cid,)); conn.commit(); conn.close()
    bot.answer_callback_query(call.id,'رفضت التحدي.'); return bot.send_message(chat_id,'❌ تم رفض التحدي.')
  cur.execute('UPDATE member_challenges SET status="playing",round_number=1,challenger_score=0,opponent_score=0,challenger_move=NULL,opponent_move=NULL WHERE id=?',(cid,))
  conn.commit(); conn.close()
  bot.answer_callback_query(call.id,'بدأ التحدي!')
  msg=bot.send_message(chat_id,'⚔️ **بدأ التحدي!**\nثلاث جولات من حجرة ورقة مقص. كل متنافس يختار حركته من الأزرار.',reply_markup=challenge_rps_keyboard(cid),parse_mode='Markdown')
  conn=sqlite3.connect(DB_FILE); cur=conn.cursor(); cur.execute('UPDATE member_challenges SET game_message_id=? WHERE id=?',(msg.message_id,cid)); conn.commit(); conn.close()


@bot.callback_query_handler(func=lambda c: c.data.startswith('ch_move_'))
def challenge_move(call):
  parts=call.data.split('_')
  try: cid=int(parts[2]); move=parts[3]
  except (ValueError, IndexError): return bot.answer_callback_query(call.id,'حركة غير صالحة.',show_alert=True)
  if move not in ('rock','paper','scissors'):
    return bot.answer_callback_query(call.id,'حركة غير صالحة.',show_alert=True)
  conn=sqlite3.connect(DB_FILE); cur=conn.cursor()
  cur.execute('SELECT chat_id,challenger_id,opponent_id,status,round_number,challenger_score,opponent_score,challenger_move,opponent_move,game_message_id FROM member_challenges WHERE id=?',(cid,))
  row=cur.fetchone()
  if not row: conn.close(); return bot.answer_callback_query(call.id,'التحدي غير موجود.',show_alert=True)
  chat_id,challenger,opponent,status,round_no,cs,oscore,cmove,omove,msg_id=row
  uid=call.from_user.id
  if uid not in (challenger,opponent): conn.close(); return bot.answer_callback_query(call.id,'هذا التحدي ليس لك.',show_alert=True)
  if status!='playing': conn.close(); return bot.answer_callback_query(call.id,'انتهى هذا التحدي.',show_alert=True)
  if uid==challenger:
    cmove=move
  else:
    omove=move
  cur.execute('UPDATE member_challenges SET challenger_move=?,opponent_move=? WHERE id=?',(cmove,omove,cid)); conn.commit()
  if not cmove or not omove:
    conn.close(); return bot.answer_callback_query(call.id,'تم تسجيل حركتك؛ ننتظر المتنافس الآخر.')
  winner=None
  if cmove != omove:
    if (cmove,omove) in (('rock','scissors'),('paper','rock'),('scissors','paper')):
      cs += 1; winner=challenger
    else:
      oscore += 1; winner=opponent
  round_text = {'rock':'حجرة','paper':'ورقة','scissors':'مقص'}
  round_result = 'تعادل الجولة' if winner is None else ('فاز المتحدّي بالجولة' if winner==challenger else 'فاز المدعو بالجولة')
  if round_no >= 3:
    cur.execute('UPDATE member_challenges SET status="finished",challenger_score=?,opponent_score=?,challenger_move=?,opponent_move=? WHERE id=?',(cs,oscore,cmove,omove,cid)); conn.commit(); conn.close()
    if cs > oscore:
      award_points(chat_id,challenger,points=3,win=True); award_points(chat_id,opponent,points=1)
      outcome='🏆 فاز صاحب التحدي!'
    elif oscore > cs:
      award_points(chat_id,opponent,points=3,win=True); award_points(chat_id,challenger,points=1)
      outcome='🏆 فاز العضو الذي قَبِل التحدي!'
    else:
      award_points(chat_id,challenger,points=1); award_points(chat_id,opponent,points=1)
      outcome='🤝 انتهى التحدي بالتعادل.'
    bot.answer_callback_query(call.id,'تم تسجيل النتيجة النهائية.')
    try: bot.edit_message_text(chat_id=chat_id,message_id=msg_id,text=f'⚔️ **انتهى التحدي بعد 3 جولات**\nالنتيجة: {cs} - {oscore}\n{outcome}',parse_mode='Markdown')
    except Exception: bot.send_message(chat_id,f'⚔️ انتهى التحدي: {cs} - {oscore}. {outcome}')
    return
  cur.execute('UPDATE member_challenges SET round_number=?,challenger_score=?,opponent_score=?,challenger_move=NULL,opponent_move=NULL WHERE id=?',(round_no+1,cs,oscore,cid)); conn.commit(); conn.close()
  bot.answer_callback_query(call.id,f'{round_result}.')
  text=f'⚔️ **نتيجة الجولة {round_no}**\nحركة المتحدّي: {round_text[cmove]}\nحركة الطرف الآخر: {round_text[omove]}\n{round_result}\n\n**النتيجة الحالية:** {cs} - {oscore}\nالجولة التالية: {round_no+1}/3'
  try: bot.edit_message_text(chat_id=chat_id,message_id=msg_id,text=text,reply_markup=challenge_rps_keyboard(cid),parse_mode='Markdown')
  except Exception: bot.send_message(chat_id,text,reply_markup=challenge_rps_keyboard(cid),parse_mode='Markdown')


# 🛒 تذكير واضح بشأن متجر الألوان والرتب
