# 🧩 الردود المخصصة: للأدمنية والرتب الأعلى فقط
custom_reply_states = {}

def can_manage_custom_replies(message):
  user = message.from_user
  if is_developer(user):
    return True
  if RANK_LEVELS.get(get_user_rank_db(message.chat.id, user.id), 1) >= 3:
    return True
  try:
    member = bot.get_chat_member(message.chat.id, user.id)
    return member.status in ('creator', 'administrator')
  except Exception:
    return False

@bot.message_handler(func=lambda m: bool(m.text) and m.text.strip() in ['اضف رد', 'أضف رد'])
def begin_custom_reply(message):
  if message.chat.type == 'private':
    return bot.send_message(message.chat.id, 'هذا الأمر استخدمه داخل المجموعة التي تريد إضافة الرد فيها.')
  if not can_manage_custom_replies(message):
    return bot.send_message(message.chat.id, '⛔ أمر «اضف رد» للأدمنية والرتب الأعلى فقط.')
  custom_reply_states[(message.chat.id, message.from_user.id)] = {'step': 'trigger'}
  bot.send_message(message.chat.id, '✍️ اكتب الآن الكلمة أو العبارة التي تريد من البوت أن يرد عليها، مثلاً: هلا\nللإلغاء اكتب: إلغاء')

@bot.message_handler(func=lambda m: bool(m.text) and (m.chat.id, m.from_user.id) in custom_reply_states)
def custom_reply_setup_or_match(message):
  key = (message.chat.id, message.from_user.id)
  state = custom_reply_states.get(key)
  if not state:
    return
  content = message.text.strip()
  if content in ('إلغاء', 'الغاء'):
    custom_reply_states.pop(key, None)
    return bot.send_message(message.chat.id, 'تم إلغاء إضافة الرد.')
  if not can_manage_custom_replies(message):
    custom_reply_states.pop(key, None)
    return bot.send_message(message.chat.id, '⛔ لم أستطع التحقق من صلاحياتك؛ ألغيت العملية.')
  if state['step'] == 'trigger':
    if len(content) > 100:
      return bot.send_message(message.chat.id, 'العبارة طويلة جداً؛ اكتب عبارة أقصر (100 حرف أو أقل).')
    state['trigger'] = content
    state['step'] = 'response'
    return bot.send_message(message.chat.id, f'✅ الرد على «{content}» سيكون شنو؟ اكتب نص الرد الآن.')
  if state['step'] == 'response':
    if len(content) > 1000:
      return bot.send_message(message.chat.id, 'الرد طويل جداً؛ اختصره إلى 1000 حرف أو أقل.')
    trigger = state['trigger']
    conn = sqlite3.connect(DB_FILE)
    cur = conn.cursor()
    cur.execute('INSERT OR REPLACE INTO custom_replies (chat_id, trigger_text, response_text, created_by) VALUES (?, ?, ?, ?)', (message.chat.id, normalize_arabic_answer(trigger), content, message.from_user.id))
    conn.commit(); conn.close()
    custom_reply_states.pop(key, None)
    return bot.send_message(message.chat.id, f'✅ تم حفظ الرد التلقائي.\nإذا كتب أحد «{trigger}» سيرد البوت: «{content}»')

# 🛡️ المعالجة العامة والحماية
@bot.message_handler(
    func=lambda m: bool(getattr(m, 'chat', None)) and m.chat.type in ('group', 'supergroup'),
    content_types=[
        'text',
        'photo',
        'video',
        'document',
        'audio',
        'sticker',
        'animation',
        'voice',
    ],
)
def handle_group_messages(message):
  chat_id = message.chat.id
  user_id = message.from_user.id
  name = message.from_user.first_name

  # إرسال الرد المخصص إن طابقت الرسالة كاملة، مع استمرار فحص الحماية بعدها.
  if message.text and message.from_user and not message.from_user.is_bot:
    trigger = normalize_arabic_answer(message.text)
    if trigger:
      conn_reply = sqlite3.connect(DB_FILE)
      cur_reply = conn_reply.cursor()
      cur_reply.execute('SELECT response_text FROM custom_replies WHERE chat_id=? AND trigger_text=?', (chat_id, trigger))
      custom_row = cur_reply.fetchone()
      conn_reply.close()
      if custom_row:
        bot.send_message(chat_id, custom_row[0])

  if is_developer(message.from_user):
    try:
      bot.restrict_chat_member(
          chat_id,
          user_id,
          can_send_messages=True,
          can_send_media_messages=True,
          can_send_other_messages=True,
          can_add_web_page_previews=True,
      )
    except Exception:
      pass

  conn = sqlite3.connect(DB_FILE)
  cursor = conn.cursor()
  # Opportunistically purge expired mute records for this group on each message.
  cursor.execute('DELETE FROM muted_users WHERE chat_id=? AND expires_at IS NOT NULL AND expires_at<=?',
                 (chat_id, time.time()))
  cursor.execute(
      'SELECT expires_at FROM muted_users WHERE chat_id = ? AND user_id = ?',
      (chat_id, user_id),
  )
  muted_row = cursor.fetchone()
  is_muted = bool(muted_row and (muted_row[0] is None or muted_row[0] > time.time()))
  if muted_row and not is_muted:
    cursor.execute('DELETE FROM muted_users WHERE chat_id=? AND user_id=?', (chat_id, user_id))
    conn.commit()
    try:
      bot.restrict_chat_member(chat_id, user_id, can_send_messages=True,
          can_send_media_messages=True, can_send_other_messages=True, can_add_web_page_previews=True)
    except Exception:
      pass

  if is_muted and not is_developer(message.from_user):
    conn.close()
    try:
      bot.delete_message(chat_id, message.message_id)
    except Exception:
      pass
    return

  update_user_info(chat_id, message.from_user)

  cursor.execute('SELECT count FROM messages_count WHERE chat_id = ? AND user_id = ?', (chat_id, user_id))
  mrow = cursor.fetchone()
  if mrow:
    cursor.execute(
        'UPDATE messages_count SET count = count + 1 WHERE chat_id = ? AND user_id = ?',
        (chat_id, user_id),
    )
  else:
    cursor.execute(
        'INSERT INTO messages_count (chat_id, user_id, count) VALUES (?, ?, 1)', (chat_id, user_id)
    )

  cursor.execute(
      'SELECT can_stickers FROM user_inventory WHERE chat_id = ? AND user_id = ?', (chat_id, user_id)
  )
  inv_s = cursor.fetchone()
  has_sticker_perm = bool(inv_s[0]) if inv_s else False
  cursor.execute('SELECT perk_key FROM shop_owned_perks WHERE chat_id = ? AND user_id = ?', (chat_id, user_id))
  owned_perks = {row[0] for row in cursor.fetchall()}
  conn.commit()
  conn.close()

  if message.text:
    text = message.text.strip()
    text_lower = text.lower()

    if 'ايسكانور' in text_lower or 'إيسكانور' in text_lower:
      return bot.send_message(message.chat.id,
          f'أهلاً بك يا [{name}](tg://user?id={user_id})، هل ناديت الشمس؟ تامرني بشي؟ ☀️',
          parse_mode='Markdown',
      )

    if chat_id in active_games:
      game = active_games[chat_id]
      # تفكيك وترتيب تحتاجان الإجابة الدقيقة، ولا نستخدم لهما مطابقة مرنة.
      if game.get('q_type') in ('تفكيك', 'ترتيب'):
        is_correct = text.strip() in game['answer']
      else:
        normalized_text = normalize_arabic_answer(text)
        correct_answers = [normalize_arabic_answer(ans) for ans in game['answer']]
        is_correct = normalized_text in correct_answers
      if is_correct:
        reward = game['reward']
        total_points, total_wins = award_points(chat_id, user_id, points=reward_points_for_game(reward), win=True)
        del active_games[chat_id]
        save_runtime_state(chat_id, 'quiz', None)
        conn = sqlite3.connect(DB_FILE)
        cursor = conn.cursor()
        cursor.execute(
            'SELECT balance FROM bank_accounts WHERE chat_id = ? AND user_id = ?', (chat_id, user_id)
        )
        b_acc = cursor.fetchone()
        if b_acc:
          new_bal = b_acc[0] + reward
          cursor.execute(
              'UPDATE bank_accounts SET balance = ? WHERE chat_id = ? AND user_id = ?',
              (new_bal, chat_id, user_id),
          )
          conn.commit()
          bal_msg = (
              f'💰 تمت إضافة **{reward:,} دينار** لحسابك البنكي! رصيدك الآن:'
              f' **{new_bal:,} دينار**.'
          )
        else:
          bal_msg = '⚠️ ليس لديك حساب بنكي! افتح حساباً بأمر `تسجيل بالبنك`.'
        conn.close()
        return bot.send_message(message.chat.id,
            f'🎉 **إجابة صحيحة يا بطل!** [{name}](tg://user?id={user_id})\n⭐ نقاطك: {total_points} | 🎖️ مستواك: {level_for_points(total_points)}\n{bal_msg}',
            parse_mode='Markdown',
        )

  user_rank = get_user_rank_db(chat_id, user_id)
  if is_developer(message.from_user):
    return

  settings = get_protection_settings(chat_id)
  if RANK_LEVELS.get(user_rank, 1) < 3:
    if settings.get('lock_media', False) and message.content_type in [
        'photo',
        'video',
        'document',
        'audio',
        'sticker',
        'animation',
        'voice',
    ]:
      media_perk = {
          'sticker': 'sticker',
          'photo': 'photo',
          'video': 'video',
          'voice': 'voice',
          'audio': 'voice',
          'animation': 'sticker',
      }.get(message.content_type)
      if message.content_type == 'document' and getattr(message, 'document', None):
        mime_type = (message.document.mime_type or '').lower()
        if mime_type.startswith('image/'):
          media_perk = 'photo'
        elif mime_type.startswith('video/'):
          media_perk = 'video'
      allowed_by_purchase = (
          (message.content_type == 'sticker' and has_sticker_perm)
          or (media_perk is not None and media_perk in owned_perks)
      )
      if not allowed_by_purchase:
        try:
          bot.delete_message(chat_id, message.message_id)
          return
        except Exception:
          pass

    if message.text:
      text_lower = message.text.lower()
      words_in_msg = text_lower.split()
      is_bad = False
      for bw in BANNED_WORDS:
        if any(bw == w for w in words_in_msg):
          is_bad = True
          break

      if settings.get('bad_words', True) and is_bad:
        try:
          bot.delete_message(chat_id, message.message_id)
        except Exception:
          pass

        curr_warn = warnings.get(chat_id, {}).get(user_id, 0) + 1
        _set_warning_count(chat_id, user_id, curr_warn)

        if curr_warn < 3:
          bot.send_message(
              chat_id,
              f'⚠️ **تنبيه وإيقاف تجاوز!**\nعذراً [{name}](tg://user?id={user_id})، يمنع استخدام الكلمات النابية!\n📌 الإنذارات: ({curr_warn}/3)',
              parse_mode='Markdown',
          )
        else:
          _set_warning_count(chat_id, user_id, 0)
          until_time = int(time.time()) + 300
          store_mute(chat_id, user_id, until_time)
          try:
            bot.restrict_chat_member(
                chat_id, user_id, can_send_messages=False, until_date=until_time
            )
          except Exception:
            pass
          bot.send_message(
              chat_id,
              f'🔇 **تم كتم العضو تلقائياً!**\nتم كتم [{name}](tg://user?id={user_id}) لمدة **5 دقائق** بعد اكتمال الإنذارات!',
              parse_mode='Markdown',
          )

      elif settings.get('links', True) and (
          'http://' in text_lower or 'https://' in text_lower or 't.me/' in text_lower
      ):
        try:
          bot.delete_message(chat_id, message.message_id)
          bot.send_message(chat_id,
              f'⚠️ عذراً [{name}](tg://user?id={user_id})، الروابط ممنوعة في هذا الكروب!',
              parse_mode='Markdown')
        except Exception:
          pass
      elif settings.get('ads', True) and looks_like_ad(message.text):
        try:
          bot.delete_message(chat_id, message.message_id)
          bot.send_message(chat_id,
              f'📢 تم حذف إعلان محتمل من [{name}](tg://user?id={user_id})؛ الإعلانات ممنوعة في هذه المجموعة.',
              parse_mode='Markdown')
        except Exception:
          pass
      elif settings.get('spam', True) and is_repeated_message(chat_id, user_id, message.text):
        try:
          bot.delete_message(chat_id, message.message_id)
        except Exception:
          pass


bot.infinity_polling()
